// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 guess, uint256 offset) public {
        vm.assume(actor != address(0) && actor != address(c));
        offset = bound(offset, 0, 2);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        uint256 target = block.number + 1;
        vm.roll(target + offset);

        bool ok;
        vm.prank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: settle() must not succeed at or before the guess's target block.
        assertTrue(!(ok && block.number <= target));
    }
}
